public class InnerSourceEndpointStandardSourceEndpointConfigurationFactory(Action<Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointConfiguration>
{

    internal InnerSourceEndpointStandardSourceEndpointProtocolConfigurationFactory ProtocolConfigurationFactory { get; set; }

    internal InnerSourceEndpointStandardSourceEndpointNetworkingConfigurationFactory SourceNetworkingConfigurationFactory { get; set; }

    protected override Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointConfiguration Create()
    {
        var standardSourceEndpointConfigurationResult = CreateStandardSourceEndpointConfiguration();
        factoryAction?.Invoke(standardSourceEndpointConfigurationResult);

        return standardSourceEndpointConfigurationResult;
    }

    private Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointConfiguration CreateStandardSourceEndpointConfiguration()
    {
        var standardSourceEndpointConfigurationResult = new Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointConfiguration();

        return standardSourceEndpointConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointConfiguration result)
    {
        base.CreateChildren(result);

        result.ProtocolConfiguration ??= ProtocolConfigurationFactory?.Build();
        result.SourceNetworkingConfiguration ??= SourceNetworkingConfigurationFactory?.Build();
    }

} // End Of Class

